update public.lessons set summary = 'Năng lượng trên Trái Đất chủ yếu có nguồn gốc từ Mặt Trời; năng lượng hoá thạch có hạn và gây ô nhiễm môi trường.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and summary is null;
