insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'objective', 'Đề xuất biện pháp sử dụng năng lượng tiết kiệm, hiệu quả.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.content = 'Đề xuất biện pháp sử dụng năng lượng tiết kiệm, hiệu quả.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'requirement', 'Dựa vào sơ đồ (hoặc hình ảnh) mô tả được sơ lược vòng năng lượng trên Trái Đất.', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.content = 'Dựa vào sơ đồ (hoặc hình ảnh) mô tả được sơ lược vòng năng lượng trên Trái Đất.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'requirement', 'Nêu được sơ lược về nhiên liệu hoá thạch; lấy ví dụ chứng tỏ việc khai thác, sử dụng nhiên liệu hoá thạch có thể gây ô nhiễm môi trường.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.content = 'Nêu được sơ lược về nhiên liệu hoá thạch; lấy ví dụ chứng tỏ việc khai thác, sử dụng nhiên liệu hoá thạch có thể gây ô nhiễm môi trường.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'knowledge', 'text', '1. Vòng năng lượng trên Trái Đất', 'Mặt Trời là nguồn năng lượng chủ yếu của Trái Đất. Năng lượng Mặt Trời:
• làm nóng mặt đất, nước bay hơi tạo thành mây, mưa → năng lượng của dòng nước (thuỷ năng);
• làm không khí nóng không đều → gió (phong năng);
• được thực vật hấp thụ qua quang hợp → năng lượng hoá học trong sinh vật; xác sinh vật bị chôn vùi hàng triệu năm → nhiên liệu hoá thạch.
Năng lượng luôn được chuyển hoá từ dạng này sang dạng khác và cuối cùng phần lớn trở thành nhiệt toả ra môi trường.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.section = 'knowledge' and x.title = '1. Vòng năng lượng trên Trái Đất');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'knowledge', 'text', '2. Năng lượng hoá thạch', 'Nhiên liệu hoá thạch gồm than đá, dầu mỏ, khí tự nhiên – hình thành từ xác sinh vật qua hàng triệu năm.
Ưu điểm: dễ khai thác, sử dụng; năng suất toả nhiệt cao; công nghệ phổ biến.
Nhược điểm: không tái tạo được, đang cạn kiệt; khi đốt cháy sinh ra CO₂ (khí nhà kính), SO₂, bụi mịn… gây ô nhiễm môi trường, biến đổi khí hậu, mưa axit.', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.section = 'knowledge' and x.title = '2. Năng lượng hoá thạch');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'knowledge', 'formula', 'Nhiệt lượng toả ra khi đốt nhiên liệu', 'Q = q · m

Trong đó: Q – nhiệt lượng toả ra (J); q – năng suất toả nhiệt của nhiên liệu (J/kg); m – khối lượng nhiên liệu bị đốt cháy hoàn toàn (kg).
Năng suất toả nhiệt (giá trị tham khảo): than đá ≈ 27·10⁶ J/kg; dầu hoả ≈ 44·10⁶ J/kg; khí đốt ≈ 44·10⁶ J/kg.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.section = 'knowledge' and x.title = 'Nhiệt lượng toả ra khi đốt nhiên liệu');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'knowledge', 'text', '3. Sử dụng năng lượng tiết kiệm', 'Tắt thiết bị khi không dùng; dùng đèn LED, thiết bị có nhãn năng lượng; đi xe đạp, phương tiện công cộng; tăng cường sử dụng năng lượng tái tạo.', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.section = 'knowledge' and x.title = '3. Sử dụng năng lượng tiết kiệm');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16), 'experiment', 'text', 'Hoạt động SGK: Sơ đồ vòng năng lượng', 'Dựa vào sơ đồ, mô tả đường đi của năng lượng Mặt Trời: chiếu tới Trái Đất → làm nóng không khí, đất, nước (gió, mưa, dòng chảy) → thực vật quang hợp → động vật → nhiên liệu hoá thạch; cuối cùng năng lượng toả ra môi trường dưới dạng nhiệt.
Thảo luận: ảnh hưởng của việc khai thác, sử dụng than đá, dầu mỏ, khí tự nhiên đến môi trường.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 16) and x.section = 'experiment' and x.title = 'Hoạt động SGK: Sơ đồ vòng năng lượng');

