update public.lessons set summary = 'Năng lượng tái tạo được bổ sung liên tục từ tự nhiên: Mặt Trời, gió, nước, sóng, địa nhiệt, sinh khối.' where id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and summary is null;
