insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'objective', 'Giải thích được vai trò của năng lượng tái tạo đối với phát triển bền vững.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.content = 'Giải thích được vai trò của năng lượng tái tạo đối với phát triển bền vững.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'objective', 'Tính được công suất của một số hệ thống năng lượng tái tạo đơn giản.', 3 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.content = 'Tính được công suất của một số hệ thống năng lượng tái tạo đơn giản.');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'requirement', 'Lấy được ví dụ về một số dạng năng lượng tái tạo và cách khai thác chúng (năng lượng Mặt Trời, gió, sóng biển, thuỷ điện, địa nhiệt…).', 1 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.content = 'Lấy được ví dụ về một số dạng năng lượng tái tạo và cách khai thác chúng (năng lượng Mặt Trời, gió, sóng biển, thuỷ điện, địa nhiệt…).');
insert into public.learning_objectives (lesson_id, kind, content, sort_order) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'requirement', 'Nêu được ưu điểm, nhược điểm của năng lượng tái tạo.', 2 where not exists (select 1 from public.learning_objectives x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.content = 'Nêu được ưu điểm, nhược điểm của năng lượng tái tạo.');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'knowledge', 'text', '1. Năng lượng tái tạo', 'Năng lượng tái tạo là năng lượng từ những nguồn liên tục được bổ sung trong tự nhiên, gần như không cạn kiệt: năng lượng Mặt Trời, gió, nước (thuỷ điện), sóng biển, thuỷ triều, địa nhiệt, sinh khối.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'knowledge' and x.title = '1. Năng lượng tái tạo');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'knowledge', 'text', '2. Một số dạng năng lượng tái tạo', '• Năng lượng Mặt Trời: pin quang điện biến quang năng thành điện năng; bình nước nóng năng lượng Mặt Trời.
• Năng lượng gió: tua-bin gió biến động năng của gió thành điện năng.
• Thuỷ điện: nước từ hồ chứa trên cao chảy xuống làm quay tua-bin (thế năng → động năng → điện năng).
• Sóng biển, thuỷ triều; địa nhiệt (nhiệt trong lòng đất); sinh khối (gỗ, phụ phẩm nông nghiệp, khí sinh học).', 2, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'knowledge' and x.title = '2. Một số dạng năng lượng tái tạo');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'knowledge', 'text', '3. Ưu điểm và nhược điểm', 'Ưu điểm: nguồn gần như vô tận; ít phát thải khí nhà kính, ít ô nhiễm; góp phần bảo đảm an ninh năng lượng.
Nhược điểm: phụ thuộc thời tiết, địa hình (không có nắng, gió liên tục); chi phí đầu tư ban đầu cao; cần diện tích lớn; thuỷ điện có thể ảnh hưởng đến hệ sinh thái.', 3, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'knowledge' and x.title = '3. Ưu điểm và nhược điểm');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'knowledge', 'formula', 'Một số công thức tham khảo', '• Pin Mặt Trời: P = H · S · η   (H – cường độ bức xạ, W/m²; S – diện tích tấm pin, m²; η – hiệu suất).
• Thuỷ điện: P = η · 10 · m · h / t   (công của trọng lực khi khối nước m rơi độ cao h trong thời gian t).', 4, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'knowledge' and x.title = 'Một số công thức tham khảo');
insert into public.lesson_materials (lesson_id, section, kind, title, body, sort_order, is_published) select (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17), 'experiment', 'text', 'Hoạt động SGK: Tìm hiểu năng lượng tái tạo', 'Tìm hiểu nguyên tắc hoạt động của pin Mặt Trời, tua-bin gió, nhà máy thuỷ điện; so sánh ưu, nhược điểm.
Liên hệ Việt Nam: các nhà máy điện Mặt Trời, điện gió ở Ninh Thuận, Bình Thuận; thuỷ điện Hoà Bình, Sơn La.', 1, true where not exists (select 1 from public.lesson_materials x where x.lesson_id = (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 17) and x.section = 'experiment' and x.title = 'Hoạt động SGK: Tìm hiểu năng lượng tái tạo');


