insert into public.question_bank (code, lesson_id, type, level, content, answer_number, tolerance, unit, explanation, formula, remember, points, source, status, sort_order) values ('B2-01', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-VL' and l.number = 2), 'multiple_choice', 'biet', 'Động năng của một vật phụ thuộc vào những yếu tố nào?', null, 0, null, 'Động năng Wđ = ½mv² phụ thuộc vào khối lượng m và tốc độ v của vật.', 'Wđ = ½·m·v²', 'Vật đứng yên có động năng bằng 0.', 1, 'PHYSICS AI – câu hỏi mẫu', 'published', 1) on conflict (code) do update set lesson_id = excluded.lesson_id, type = excluded.type, level = excluded.level, content = excluded.content, answer_number = excluded.answer_number, tolerance = excluded.tolerance, unit = excluded.unit, explanation = excluded.explanation, formula = excluded.formula, remember = excluded.remember, sort_order = excluded.sort_order;
